constraints:
1 ≤ K ≤ |S| ≤ 10^{5}

expected time complexity: O(|S|)
expected auxiliary space: O(constant)

standard_solution_code:
class Solution:

	def countOfSubstrings(self, s, k):
		count = 0
		dic = {}
		i = 0
		j = 0
		while j < len(s):
			if s[j] in dic:
				dic[s[j]] += 1
			else:
				dic[s[j]] = 1
			if j - i + 1 == k:
				if len(dic) == k - 1:
					count += 1
			elif j - i + 1 > k:
				dic[s[i]] -= 1
				if dic[s[i]] == 0:
					del dic[s[i]]
				i += 1
				if len(dic) == k - 1:
					count += 1
			j += 1
		return count
